import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
const t = k => app.translator.trans('ernestdefoe-roster.admin.' + k);
/**
 * Which competitions get rosters, as tick boxes over one comma-joined setting.
 *
 * 🚨 College football is deliberately absent. It is CollegeFootballData's, not
 * ESPN's, and it is not optional — offering it here as a box would suggest it
 * can be switched off, and unticking it would silently do nothing.
 */
export default class LeaguePicker extends Component {
  chosen() {
    return String(this.attrs.value() || '').split(',').map(s => s.trim()).filter(Boolean);
  }
  toggle(key, on) {
    const chosen = this.chosen();
    const next = on ? [...new Set([...chosen, key])] : chosen.filter(k => k !== key);
    this.attrs.value(next.join(','));
  }
  view() {
    /*
     * 🚨 From the SERVER's registry, never a copy written here. A second list
     * in the bundle goes stale the first time an extension registers a league,
     * which is the whole reason the registry exists.
     */
    const registry = app.data?.rosterLeagues ?? {};
    const chosen = this.chosen();
    const keys = Object.keys(registry).filter(key => key !== 'cfb');
    return m("div", {
      className: "Form-group RosterLeagues"
    }, m("label", null, t('leagues_label')), m("div", {
      className: "helpText"
    }, t('leagues_help')), keys.length === 0 ? m("div", {
      className: "helpText"
    }, t('leagues_empty')) : null, keys.map(key => m("label", {
      className: "checkbox"
    }, m("input", {
      type: "checkbox",
      checked: chosen.includes(key),
      onchange: e => this.toggle(key, e.target.checked)
    }), registry[key])));
  }
}
flarum.reg.add('ernestdefoe-roster', 'admin/components/LeaguePicker', LeaguePicker);